medad como baños y cocinas.', 420.0, NULL, 0.0, '15', 'Saco', 12, '14', NULL, NULL, NULL, NULL, 'Impermeabilizante, Mortero, Saco', 'https://drive.google.com/file/d/1d_A1Z-3_dOWfACuh2NG07yTRF85vMey_/view', 'https://res.cloudinary.com/ugxdkwes/image/upload/v1788384982/edificando/perfiles/apieinwlxxyqdp49kxo2.jpg', TRUE, '2026-09-02T21:36:23.096598', FALSE) ON CONFLICT DO NOTHING;
